head.script:
scwin.screenId = "jldfil71204";

///////// 1. 변수 및 선언 영역 /////////

// as-is 흐름 보존 — 스켈레톤이 대체한 함수가 쓰던 전역 선언
scwin.form = undefined;


///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.init();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil71204.onpageload' }); }
};

// [A] 초기 목록 미해결 — jldfil71204: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil71204.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @method
 * @name scwin.btn_Search_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_Search_onclick = async function(e){
    const ev = e;
    const event = ev;
    const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
    /* sdd-asis-lifecycle:begin btn_Search_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    await scwin.search()
    /* sdd-asis-lifecycle:end */
};

/**
 * @event
 * @name scwin.__ev_2_btn_Search_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.__ev_2_btn_Search_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin __ev_2_btn_Search_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.search()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil71204.__ev_2_btn_Search_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_Search_2_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_Search_2_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_Search_2_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.search()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil71204.btn_Search_2_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_EtnChangePage
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_EtnChangePage = async function () {
    const sbmOptions = {
        id: "tx_fn_EtnChangePage",
        method: "post",
        action: "/etn/LossLimitEtnList.do",
        ref: "dma_EtnChangePageReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil71204.tx_fn_EtnChangePage" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fn_Search
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_Search = async function () {
    const sbmOptions = {
        id: "tx_fn_Search",
        method: "post",
        action: "/etn/EtnList.do",
        ref: "dma_SearchReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil71204.tx_fn_Search" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.etnChangePage
 * @author Inswave
 * @date 2026. 09. 29
 * @param tab
 * @returns
 * @hidden N
*/
scwin.etnChangePage = async function (tab) {
    /* sdd-asis-lifecycle:begin fn_EtnChangePage — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.form = (document.etnListForm || { elements: [] });
    const lastSaveStatCdInt = parseInt($c.util.getComponent('dma_EtnChangePageReq').get('lastSaveStatCd'));
    if (tab == 1) {
        $c.util.getComponent('dma_EtnChangePageReq').set('method', 'lossLimitViewIsuTab');
    } else {
        if (tab == 2) {
            $c.util.getComponent('dma_EtnChangePageReq').set('method', 'lossLimitViewIsuTab2');
        } else {
            if (tab == 3) {
                return;
            } else {
                if (tab == 4) {
                    $c.util.getComponent('dma_EtnChangePageReq').set('method', 'lossLimitViewSrtyLpTab');
                } else {
                    $c.util.getComponent('dma_EtnChangePageReq').set('method', 'lossLimitViewAttachFileTab');
                }
            }
        }
    }
    scwin.form.action = 'LossLimitEtnList.do';
    await scwin.tx_fn_EtnChangePage();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.search = async function () {
    /* sdd-asis-lifecycle:begin fn_Search — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.form = (document.etnListForm || { elements: [] });
    scwin.form.action = "EtnList.do";
    $c.util.getComponent('dma_EtnChangePageReq').set('listBzTpCd', "");
    $c.util.getComponent('dma_EtnChangePageReq').set('method', 'searchList');
    await scwin.tx_fn_Search();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init = function () {
    /* sdd-asis-lifecycle:begin fn_init — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.cal();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.cal
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.cal = function () {
    /* sdd-asis-lifecycle:begin fn_cal — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const isuTotamtNumber = scwin.rmComma($c.util.getComponent('txt_isuTotamt').getValue());
    const eqtycapNumber = scwin.rmComma($c.util.getComponent('txt_eqtycap').getValue());
    const isuLimit = $c.num.formatNumber(String(Math.floor(isuTotamtNumber / eqtycapNumber * 10000) / 100));
    $c.util.getComponent('txt_ncr1').setLabel($c.num.formatNumber(String($c.util.getComponent('txt_ncr1').getValue())));
    $c.util.getComponent('txt_ncr2').setLabel($c.num.formatNumber(String($c.util.getComponent('txt_ncr2').getValue())));
    $c.util.getComponent('txt_ncr3').setLabel($c.num.formatNumber(String($c.util.getComponent('txt_ncr3').getValue())));
    isuLimit.setLabel(isuLimit);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.rmComma
 * @author Inswave
 * @date 2026. 09. 29
 * @param str
 * @returns
 * @hidden N
*/
scwin.rmComma = function (str) {
    /* sdd-asis-lifecycle:begin fn_RmComma — as-is 원문 본문(전환 이관 · 포팅 적용됨) */

    //	if( str == null || str == "" || str == 0 ) return '';
    //	if( str == null || str == ""  ) return '';
    if( str == null || str === ""  ) return Number(str);			//2009.07.02 수정. 항목 미입력시 합계 오류발생

    reg =  new RegExp(",","g");  

    return Number(str.replace(reg,''));
    /* sdd-asis-lifecycle:end */
};
